INSERT INTO "frikiparty_game_map_board" ("game_map_id", "image_url", "width", "height", "rings", "halves")
SELECT m."id", b."image_url", b."width", b."height", b."rings", b."halves"
FROM "booklet_board" b
JOIN "frikiparty_game" g ON g."name" = 'Age of the Ring'
JOIN "frikiparty_game_map" m ON m."game_id" = g."id" AND m."name" = b."name"
ON CONFLICT ("game_map_id") DO UPDATE SET "image_url" = excluded."image_url", "width" = excluded."width", "height" = excluded."height", "rings" = excluded."rings", "halves" = excluded."halves";
